 pf_case('F HTTP capability exchange redirects clean then recovers assessment without email',function()use(&$httpP,&$httpF,&$httpCookies){$frame=pf_http_frame($httpP,$httpF,$httpCookies);$row=(new P\StudyExecutionRepository(pf_db()))->find($frame['access']['execution_id']);$participant=(new L\Identity(pf_db(),new L\Clock()))->participant($row['participant_id']);$cap=pf_db()->transactional(function()use($participant,$httpP,$row){return (new L\Capability(pf_db(),array('ACCESS_TEST'=>str_repeat('a',32)),'ACCESS_TEST'))->mint($participant,(new R\PublicStudyRepository(pf_db()))->find($httpP['public']),$row,'VERIFY_PARTICIPANT');});$redeemed=pf_http($httpP['public'],array(),null,$cap);pe_assert($redeemed['status']===303&&strpos($redeemed['headers']['location'],'eipsi_cap')===false,'Bearer not cleaned');$r=pf_http($httpP['public'],$redeemed['cookies']);pe_assert($r['status']===200&&$r['data']['state']==='OPEN_ASSESSMENT'&&strpos($r['data']['html'],'name="email"')===false,'Indirect link flow');});
